class User {
  constructor(userId, fullName, email, employerId, preferences) {
    // string - generated by Firebase - not editable
    this.userId = userId; // e.g 'safsafdefds21312dasda'

    // string - Entered at registration - editable
    this.fullName = fullName; // e.g Matthew Johnson

    // validated string - Entered at registration - not editable ?
    this.email = email; // e.g matt.johnson@gmail.com

    // string - set at registration based on employer selection - not editable
    this.employerId = employerId; // e.g 'safasf23eder235rdfa3'

    // object
    this.preferences = preferences;
    /* e.g { 
                'darkMode': true,       // true/false
                'language': 'English',  // English, Romanian, Italian, French
                'sort': 'ascending',    // ascending, descending
                'filter': 'location1'   // location, year, month
                'notifications': true   // true/false
            }*/
  }
}

// simple class for Time format
class Time {
  // numbers given as arguments to the constructor
  constructor(hours, minutes) {
    this.hours = hours;
    this.minutes = minutes;
  }

  // return a string of format hh:mm
  getTime() {
    const hh =
      this.hours < 10 ? '0' + this.hours.toString() : this.hours.toString();
    const mm =
      this.minutes < 10
        ? '0' + this.minutes.toString()
        : this.minutes.toString();

    return hh + ':' + mm;
  }
}

class Clocking {
  constructor(
    clockingId,
    ownerId,
    locationId,
    title,
    description,
    startTime,
    endTime,
    date
  ) {
    // string - generated by Firebase - not editable
    this.clockingId = clockingId; // '354adsf4rf4wfwe'

    // string - linked from Users database - not editable
    this.ownerId = ownerId;

    // string - linked from locations database - not editable
    this.locationId = locationId;

    // string - created based on input data - not editable
    this.title = title;

    // string - entered at creation - editable
    this.description = description;

    // Time - input from TimePicker - not editable once validated
    this.startTime = startTime;

    // Time - input from TimePicker - not editable once validated
    this.endTime = endTime;

    // Date - input from DatePicker - not editable once validated
    this.date = date;

    // boolean - set once the admin validates the entry - not editable
    this.isValidated = false;
  }
}
